CREATE TABLE IF NOT EXISTS wowforever_content_ports (
  name varchar(80) NOT NULL PRIMARY KEY,
  installed_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
DROP PROCEDURE IF EXISTS wf_remove_northshire_chain;
DELIMITER //
CREATE PROCEDURE wf_remove_northshire_chain()
main: BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  IF NOT EXISTS (SELECT 1 FROM wowforever_content_ports WHERE name='northshire-chain-335-v1') THEN
    COMMIT;
    SELECT 'Not installed; no changes' AS result;
    LEAVE main;
  END IF;
  DELETE FROM `quest_template` WHERE `ID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `quest_template_addon` WHERE `ID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `quest_classic_level` WHERE `ID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `quest_classic_money` WHERE `ID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `quest_template_classic_level` WHERE `ID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `quest_offer_reward` WHERE `ID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `quest_request_items` WHERE `ID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `quest_objectives` WHERE `QuestID` IN (910007,910015,910021,910054,910783);
  DELETE FROM `creature_template` WHERE `entry` IN (910197,910240,910823);
  DELETE FROM `creature_template_model` WHERE `CreatureID` IN (910197,910240,910823);
  DELETE FROM `creature_template_difficulty` WHERE `Entry` IN (910197,910240,910823);
  DELETE FROM `creature` WHERE `guid` IN (910000001,910000002,910000003);
  DELETE FROM `creature_queststarter` WHERE `id` IN (910197,910240,910823);
  DELETE FROM `creature_queststarter` WHERE `quest` IN (910007,910015,910021,910054,910783);
  DELETE FROM `creature_questender` WHERE `id` IN (910197,910240,910823);
  DELETE FROM `creature_questender` WHERE `quest` IN (910007,910015,910021,910054,910783);
  DELETE FROM wowforever_content_ports WHERE name='northshire-chain-335-v1';
  COMMIT;
  SELECT 'Removed Northshire chain; character progress and original quests retained' AS result;
END//
DELIMITER ;
CALL wf_remove_northshire_chain();
DROP PROCEDURE wf_remove_northshire_chain;
